/// The scenario runtime, controller/atalaia_controller/scenarios/runtime.lua,
/// as a Dart string: the code after the SCENARIO table in every compiled
/// scenario's field.lua (scenario_lua.dart).
///
/// Generated from that file by tools/scenario_compile_vectors.py: do not
/// edit it by hand. scenarios_test.dart checks that it is the same text.
library;

/// runtime.lua's text, its header included (its SPDX lines are the runtime's,
/// not this file's: REUSE skips them).
// REUSE-IgnoreStart
const String scenarioRuntimeLua =
    '-- SPDX-FileCopyrightText: 2026 The Atalaia contributors\n'
    '-- SPDX-License-Identifier: GPL-3.0-or-later\n'
    '--\n'
    '-- The scenario runtime: the code of every compiled scenario\'s field.lua,\n'
    '-- after the SCENARIO table that the compiler writes (lua.py). It is GPL, as\n'
    '-- the game modes are, because it is copied into every scenario package; the\n'
    '-- compiler that copies it is AGPL. Everything above "@runtime" stays here.\n'
    '--\n'
    '-- The data (one entry of SCENARIO.objectives):\n'
    '--   id, type      the objective\'s id (data key 34) and type\n'
    '--   team, squad   the assignee (squad as text, as events carry it); nil: any\n'
    '--   hidden        revealed only when it opens, or by another\'s reveals\n'
    '--   depends_on    ids that must be completed before it opens\n'
    '--   reveals       ids revealed when it is completed\n'
    '--   start_s       it opens no earlier than this (time_window.start_min)\n'
    '--   end_s         nil, or when it fails if still open (survive: is judged)\n'
    '--   points        points for the team that completes it, or points_param:\n'
    '--                 the name of a scenario parameter that holds them\n'
    '--   win           completing it wins the game for that team\n'
    '--   node, setup   a box\'s objective: the node\'s name and its setup command\n'
    '--   duration_s    capture_and_hold: how long to hold (0: the capture);\n'
    '--                 defend: how long to keep it from when it opens\n'
    '--   role, zone,   escort: the player\'s check-in role, the destination\n'
    '--   max_acc_m     (geo.in_zone), the worst GPS accuracy that counts\n'
    '--   minimum_lives survive\n'
    '--\n'
    '-- An objective is waiting, then open, then done or failed ("off": its team\n'
    '-- is not in this game). It opens when it is revealed (at the start unless\n'
    '-- hidden; a hidden one when it could open, or by a reveals), its time window\n'
    '-- has started and what it depends on is done. A failed one fails what\n'
    '-- depends on it ("blocked"). Events about an objective that was never\n'
    '-- revealed are not sent (P4R24). The boxes only report; this script decides,\n'
    '-- scores and tells each box what it is for (the mode command "setup") at the\n'
    '-- start, when the box first appears, and again after a reboot. Nothing\n'
    '-- secret goes into state.field (players read it); positions stay in this\n'
    '-- script (P4R6).\n'
    '-- @runtime\n'
    'local OBJ = SCENARIO.objectives\n'
    'local by_id = {}\n'
    'for _, o in ipairs(OBJ) do\n'
    '  by_id[o.id] = o\n'
    'end\n'
    '\n'
    'local status = {} -- id -> waiting, open, done, failed, off\n'
    'local revealed = {} -- id -> true once scenario.objective.revealed was sent\n'
    'local started = {} -- id -> true once its time window started\n'
    'local winner = {} -- id -> the team that completed it\n'
    'local configured = {} -- id -> the node id its setup reached\n'
    'local holder = {} -- capture_and_hold, defend: id -> the team holding its node\n'
    'local scanned = {} -- scan_tags: id -> { counts = { team -> n }, team -> { tag -> true } }\n'
    'local armed = {} -- destroy: id -> { team, explode_at }\n'
    'local timer = {} -- capture_and_hold, defend: id -> the timer that completes it\n'
    'local lives = {} -- survive: team -> lives left, as Respawn last reported them\n'
    '\n'
    'local function in_game(team)\n'
    '  if team == nil then\n'
    '    return true\n'
    '  end\n'
    '  for _, t in ipairs(game.teams()) do\n'
    '    if t == team then\n'
    '      return true\n'
    '    end\n'
    '  end\n'
    '  return false\n'
    'end\n'
    '\n'
    'local function node_id(o)\n'
    '  if o.node == nil then\n'
    '    return nil\n'
    '  end\n'
    '  for _, n in ipairs(field.nodes()) do\n'
    '    if n.name == o.node then\n'
    '      return n.id\n'
    '    end\n'
    '  end\n'
    'end\n'
    '\n'
    'local function objective_at(id)\n'
    '  for _, o in ipairs(OBJ) do\n'
    '    if o.node and (configured[o.id] == id or node_id(o) == id) then\n'
    '      return o\n'
    '    end\n'
    '  end\n'
    'end\n'
    '\n'
    'local function open_at(id, type_)\n'
    '  local o = objective_at(id)\n'
    '  if o and status[o.id] == "open" and (type_ == nil or type_[o.type]) then\n'
    '    return o\n'
    '  end\n'
    'end\n'
    '\n'
    'local function setup(o)\n'
    '  local id = node_id(o)\n'
    '  if id == nil then\n'
    '    return\n'
    '  end\n'
    '  local st = status[o.id]\n'
    '  local p = { name = "setup", label = o.setup.label, lang = o.setup.lang }\n'
    '  if st == "done" or st == "failed" then\n'
    '    p.kind, p.team = st, winner[o.id]\n'
    '  elseif st ~= "open" then\n'
    '    p.kind = "off"\n'
    '  else\n'
    '    for k, v in pairs(o.setup) do\n'
    '      p[k] = v\n'
    '    end\n'
    '    p.holder = holder[o.id]\n'
    '    local s = scanned[o.id]\n'
    '    if s and o.team then\n'
    '      p.have = s.counts[o.team]\n'
    '    end\n'
    '    local a = armed[o.id]\n'
    '    if a then\n'
    '      p.armed, p.left = a.team, math.max(1, math.ceil(a.explode_at - game.time()))\n'
    '    end\n'
    '  end\n'
    '  if field.send(id, "mode", p) then\n'
    '    configured[o.id] = id\n'
    '  end\n'
    'end\n'
    '\n'
    'local function event(type_, o, team, reason)\n'
    '  local d = { objective = o.id, team = team, reason = reason }\n'
    '  if o.squad and team ~= nil and team == o.team then\n'
    '    d.squad = o.squad\n'
    '  end\n'
    '  emit(type_, d)\n'
    'end\n'
    '\n'
    'local function stop_timer(o)\n'
    '  if timer[o.id] then\n'
    '    cancel(timer[o.id])\n'
    '    timer[o.id] = nil\n'
    '  end\n'
    'end\n'
    '\n'
    'local refresh -- below: opens an objective when it can\n'
    '\n'
    'local function reveal(o)\n'
    '  if revealed[o.id] or status[o.id] == "off" then\n'
    '    return\n'
    '  end\n'
    '  revealed[o.id] = true\n'
    '  event("scenario.objective.revealed", o, o.team)\n'
    'end\n'
    '\n'
    'local function depends_on(o, id)\n'
    '  for _, d in ipairs(o.depends_on) do\n'
    '    if d == id then\n'
    '      return true\n'
    '    end\n'
    '  end\n'
    '  return false\n'
    'end\n'
    '\n'
    'local function fail(o, team, reason)\n'
    '  local st = status[o.id]\n'
    '  if st ~= "waiting" and st ~= "open" then\n'
    '    return\n'
    '  end\n'
    '  status[o.id] = "failed"\n'
    '  stop_timer(o)\n'
    '  armed[o.id] = nil\n'
    '  if revealed[o.id] then\n'
    '    event("scenario.objective.failed", o, team, reason)\n'
    '  end\n'
    '  if o.node then\n'
    '    setup(o)\n'
    '  end\n'
    '  for _, d in ipairs(OBJ) do\n'
    '    if depends_on(d, o.id) then\n'
    '      fail(d, d.team, "blocked")\n'
    '    end\n'
    '  end\n'
    'end\n'
    '\n'
    'local function finish(o, team)\n'
    '  if status[o.id] ~= "open" then\n'
    '    return\n'
    '  end\n'
    '  status[o.id], winner[o.id] = "done", team\n'
    '  stop_timer(o)\n'
    '  armed[o.id] = nil\n'
    '  event("scenario.objective.completed", o, team)\n'
    '  local points = o.points\n'
    '  if o.points_param then\n'
    '    points = params[o.points_param]\n'
    '  end\n'
    '  if team and points and points > 0 then\n'
    '    score.add(team, points, "objective")\n'
    '  end\n'
    '  if o.node then\n'
    '    setup(o)\n'
    '  end\n'
    '  for _, id in ipairs(o.reveals) do\n'
    '    reveal(by_id[id])\n'
    '    refresh(by_id[id])\n'
    '  end\n'
    '  for _, d in ipairs(OBJ) do\n'
    '    if depends_on(d, o.id) then\n'
    '      refresh(d)\n'
    '    end\n'
    '  end\n'
    '  if o.win and team then\n'
    '    game.win(team)\n'
    '  end\n'
    'end\n'
    '\n'
    'local function hold_for(o, team, seconds)\n'
    '  stop_timer(o)\n'
    '  timer[o.id] = after(seconds, function()\n'
    '    timer[o.id] = nil\n'
    '    if holder[o.id] == team then\n'
    '      finish(o, team)\n'
    '    end\n'
    '  end)\n'
    'end\n'
    '\n'
    'local function opened(o)\n'
    '  if o.type == "defend" then\n'
    '    holder[o.id] = o.team -- the defenders hold it; an enemy capture fails it\n'
    '    timer[o.id] = after(o.duration_s, function()\n'
    '      timer[o.id] = nil\n'
    '      finish(o, o.team)\n'
    '    end)\n'
    '  end\n'
    'end\n'
    '\n'
    'refresh = function(o)\n'
    '  if status[o.id] ~= "waiting" or not started[o.id] then\n'
    '    return\n'
    '  end\n'
    '  for _, d in ipairs(o.depends_on) do\n'
    '    if status[d] ~= "done" then\n'
    '      return\n'
    '    end\n'
    '  end\n'
    '  reveal(o)\n'
    '  status[o.id] = "open"\n'
    '  opened(o)\n'
    '  if o.node then\n'
    '    setup(o)\n'
    '  end\n'
    'end\n'
    '\n'
    'local function judge(o)\n'
    '  if o.type == "survive" then\n'
    '    if status[o.id] == "open" then\n'
    '      finish(o, o.team)\n'
    '    else\n'
    '      fail(o, o.team, "time")\n'
    '    end\n'
    '  else\n'
    '    fail(o, o.team, "time")\n'
    '  end\n'
    'end\n'
    '\n'
    'on("game.start", function()\n'
    '  emit("scenario.started", { scenario = SCENARIO.id })\n'
    '  for _, o in ipairs(OBJ) do\n'
    '    if in_game(o.team) then\n'
    '      status[o.id] = "waiting"\n'
    '      started[o.id] = o.start_s == 0\n'
    '    else\n'
    '      status[o.id] = "off"\n'
    '      log("scenario: " .. o.id .. " is off: its team is not in this game")\n'
    '    end\n'
    '  end\n'
    '  for _, o in ipairs(OBJ) do\n'
    '    if status[o.id] == "waiting" and not o.hidden then\n'
    '      reveal(o)\n'
    '    end\n'
    '  end\n'
    '  for _, o in ipairs(OBJ) do\n'
    '    refresh(o)\n'
    '    if o.node and status[o.id] ~= "open" then\n'
    '      setup(o)\n'
    '    end\n'
    '    if status[o.id] ~= "off" then\n'
    '      if o.start_s > 0 then\n'
    '        after(o.start_s, function()\n'
    '          started[o.id] = true\n'
    '          refresh(o)\n'
    '        end)\n'
    '      end\n'
    '      if o.end_s then\n'
    '        after(o.end_s, function()\n'
    '          judge(o)\n'
    '        end)\n'
    '      end\n'
    '    end\n'
    '  end\n'
    'end)\n'
    '\n'
    '-- A node that joins later is set up when it first appears.\n'
    'every(1, function()\n'
    '  for _, o in ipairs(OBJ) do\n'
    '    if o.node and status[o.id] and not configured[o.id] then\n'
    '      setup(o)\n'
    '    end\n'
    '  end\n'
    'end)\n'
    '\n'
    '-- A rebooted node lost its setup (no script state survives a reboot): send it again.\n'
    'on("node.rebooted", function(e)\n'
    '  for _, o in ipairs(OBJ) do\n'
    '    if o.node and configured[o.id] == e.node then\n'
    '      configured[o.id] = nil\n'
    '      setup(o)\n'
    '    end\n'
    '  end\n'
    'end)\n'
    '\n'
    '-- capture_and_hold and defend.\n'
    '\n'
    'local CAPTURE = { capture_and_hold = true, defend = true }\n'
    '\n'
    'on("zone.captured", function(e)\n'
    '  local o = open_at(e.node, CAPTURE)\n'
    '  if o == nil then\n'
    '    return\n'
    '  end\n'
    '  holder[o.id] = e.team\n'
    '  if o.type == "defend" then\n'
    '    if e.team ~= o.team then\n'
    '      fail(o, o.team, "captured")\n'
    '    end\n'
    '  elseif o.team == nil or e.team == o.team then\n'
    '    if o.duration_s == 0 then\n'
    '      finish(o, e.team)\n'
    '    else\n'
    '      hold_for(o, e.team, o.duration_s)\n'
    '    end\n'
    '  end\n'
    'end)\n'
    '\n'
    'on("zone.neutralized", function(e)\n'
    '  local o = open_at(e.node, CAPTURE)\n'
    '  if o then\n'
    '    holder[o.id] = nil\n'
    '    if o.type == "capture_and_hold" then\n'
    '      stop_timer(o)\n'
    '    end\n'
    '  end\n'
    'end)\n'
    '\n'
    '-- enter_code: the box checks the code; code.used never carries it.\n'
    '\n'
    'on("code.used", function(e)\n'
    '  local o = open_at(e.node, { enter_code = true })\n'
    '  if o then\n'
    '    finish(o, e.team or o.team)\n'
    '  end\n'
    'end)\n'
    '\n'
    '-- scan_tags: each tag counts once per team, even if the box rebooted and forgot it.\n'
    '\n'
    'on("tag.scanned", function(e)\n'
    '  local o = open_at(e.node, { scan_tags = true })\n'
    '  if o == nil or type(e.team) ~= "string" or (o.team and e.team ~= o.team) then\n'
    '    return\n'
    '  end\n'
    '  local s = scanned[o.id] or { counts = {} }\n'
    '  scanned[o.id] = s\n'
    '  s[e.team] = s[e.team] or {}\n'
    '  if s[e.team][e.tag] then\n'
    '    return\n'
    '  end\n'
    '  s[e.team][e.tag] = true\n'
    '  s.counts[e.team] = (s.counts[e.team] or 0) + 1\n'
    '  if s.counts[e.team] >= o.setup.count then\n'
    '    finish(o, e.team)\n'
    '  end\n'
    'end)\n'
    '\n'
    '-- destroy: completed when the bomb explodes, failed when it is defused.\n'
    '\n'
    'on("bomb.armed", function(e)\n'
    '  local o = open_at(e.node, { destroy = true })\n'
    '  if o then\n'
    '    armed[o.id] = { team = e.team, explode_at = game.time() + (e.fuse_s or o.setup.fuse_s or 60) }\n'
    '  end\n'
    'end)\n'
    '\n'
    'on("bomb.defused", function(e)\n'
    '  local o = open_at(e.node, { destroy = true })\n'
    '  if o then\n'
    '    local a = armed[o.id]\n'
    '    fail(o, o.team or (a and a.team), "defused")\n'
    '  end\n'
    'end)\n'
    '\n'
    'on("bomb.exploded", function(e)\n'
    '  local o = open_at(e.node, { destroy = true })\n'
    '  if o then\n'
    '    local a = armed[o.id]\n'
    '    finish(o, e.team or o.team or (a and a.team))\n'
    '  end\n'
    'end)\n'
    '\n'
    '-- escort: the controller hands this script the positions of checked-in players\n'
    '-- (position.fix, P4R6); a fix of the escorted role inside the zone completes it.\n'
    '\n'
    'on("position.fix", function(e)\n'
    '  if type(e.lat) ~= "number" or type(e.lon) ~= "number" then\n'
    '    return\n'
    '  end\n'
    '  for _, o in ipairs(OBJ) do\n'
    '    if\n'
    '      o.type == "escort"\n'
    '      and status[o.id] == "open"\n'
    '      and e.role == o.role\n'
    '      and (o.team == nil or e.team == o.team)\n'
    '      and not (type(e.acc) == "number" and e.acc > o.max_acc_m)\n'
    '      and geo.in_zone(e.lat, e.lon, o.zone)\n'
    '    then\n'
    '      finish(o, e.team)\n'
    '    end\n'
    '  end\n'
    'end)\n'
    '\n'
    '-- survive: Respawn and Lives\' reports (lives per team; per-player lives say\n'
    '-- nothing about a team\'s).\n'
    '\n'
    'local function lives_changed(team)\n'
    '  for _, o in ipairs(OBJ) do\n'
    '    if o.type == "survive" and o.team == team and status[o.id] ~= "done" then\n'
    '      local left = lives[team]\n'
    '      if left ~= nil and (left < 0 or left < o.minimum_lives) then\n'
    '        fail(o, team, "lives")\n'
    '      end\n'
    '    end\n'
    '  end\n'
    'end\n'
    '\n'
    'on("player.respawn", function(e)\n'
    '  if params.per_player or type(e.team) ~= "string" or math.type(e.lives_left) ~= "integer" then\n'
    '    return\n'
    '  end\n'
    '  lives[e.team] = e.lives_left\n'
    '  lives_changed(e.team)\n'
    'end)\n'
    '\n'
    'on("team.eliminated", function(e)\n'
    '  if type(e.team) == "string" then\n'
    '    lives[e.team] = -1\n'
    '    lives_changed(e.team)\n'
    '  end\n'
    'end)\n';
// REUSE-IgnoreEnd
